import { AppwriteError } from "./appwrite";

export class OrpError extends Error {
  readonly statusCode: number;

  constructor(message: string, statusCode = 400) {
    super(message);
    this.name = "OrpError";
    this.statusCode = statusCode;
  }
}

function logInternalError(error: unknown): void {
  const payload =
    error instanceof AppwriteError
      ? {
          name: error.name,
          message: error.message,
          status: error.status,
          type: error.type,
          method: error.method,
          path: error.path,
          stack: error.stack,
        }
      : error instanceof Error
        ? {
            name: error.name,
            message: error.message,
            stack: error.stack,
          }
        : { value: String(error) };

  // Keep logs structured for easier filtering in Cloudflare logs.
  console.error("[orp-api-error]", JSON.stringify(payload));
}

function logHandledError(payload: Record<string, unknown>): void {
  console.warn("[orp-api-handled]", JSON.stringify(payload));
}

export function toErrorResponse(error: unknown): { statusCode: number; message: string } {
  if (error instanceof OrpError) {
    logHandledError({ type: "OrpError", statusCode: error.statusCode, message: error.message });
    return { statusCode: error.statusCode, message: error.message };
  }

  if (
    typeof error === "object" &&
    error !== null &&
    "name" in error &&
    (error as { name: string }).name === "RateLimitError" &&
    "statusCode" in error
  ) {
    logHandledError({
      type: "RateLimitError",
      statusCode: 429,
      message: (error as unknown as { message: string }).message,
    });
    return { statusCode: 429, message: (error as unknown as { message: string }).message };
  }

  if (
    typeof error === "object" &&
    error !== null &&
    "name" in error &&
    (error as { name: string }).name === "ZodError"
  ) {
    logHandledError({ type: "ZodError", statusCode: 422, message: "Invalid request payload." });
    return { statusCode: 422, message: "Invalid request payload." };
  }

  if (error instanceof AppwriteError) {
    if (error.type === "user_already_exists" || error.type === "user_email_already_exists") {
      logHandledError({
        type: "AppwriteError",
        statusCode: 409,
        message: "An account with this email already exists.",
        appwriteType: error.type,
        method: error.method,
        path: error.path,
      });
      return { statusCode: 409, message: "An account with this email already exists." };
    }

    if (error.status === 400) {
      logHandledError({
        type: "AppwriteError",
        statusCode: 422,
        message: "Invalid request payload.",
        appwriteType: error.type,
        method: error.method,
        path: error.path,
      });
      return { statusCode: 422, message: "Invalid request payload." };
    }

    if (error.status === 401) {
      logHandledError({
        type: "AppwriteError",
        statusCode: 401,
        message: "Unauthorized.",
        appwriteType: error.type,
        method: error.method,
        path: error.path,
      });
      return { statusCode: 401, message: "Unauthorized." };
    }

    if (error.status === 403) {
      logHandledError({
        type: "AppwriteError",
        statusCode: 403,
        message: "Permission denied.",
        appwriteType: error.type,
        method: error.method,
        path: error.path,
      });
      return { statusCode: 403, message: "Permission denied." };
    }

    if (error.status === 404) {
      logHandledError({
        type: "AppwriteError",
        statusCode: 404,
        message: "Not found.",
        appwriteType: error.type,
        method: error.method,
        path: error.path,
      });
      return { statusCode: 404, message: "Not found." };
    }

    if (error.status === 429) {
      logHandledError({
        type: "AppwriteError",
        statusCode: 429,
        message: "Rate limit exceeded. Try again in a minute.",
        appwriteType: error.type,
        method: error.method,
        path: error.path,
      });
      return { statusCode: 429, message: "Rate limit exceeded. Try again in a minute." };
    }

    logInternalError(error);
    return { statusCode: 500, message: "Internal server error." };
  }

  if (error instanceof Error) {
    logInternalError(error);
    return { statusCode: 500, message: "Internal server error." };
  }

  logInternalError(error);
  return { statusCode: 500, message: "Internal server error." };
}
